import React, { useState } from 'react';
import { User, Mail, Lock, Eye, EyeOff, AlertCircle, Shield } from 'lucide-react';

// Lista de emails autorizados (pode ser expandida)
const EMAILS_AUTORIZADOS = [
  'tnfsg@proton.me',
  'trifsg@proton.me',
  'admin@realestate.com',
  'corretor@realestate.com',
  'gerente@realestate.com'
];

// Senha padrão de 3 caracteres (fácil de digitar, difícil de acertar)
const SENHA_PADRAO = '@7X';

const SimpleLogin: React.FC = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [errors, setErrors] = useState<{[key: string]: string}>({});
  const [isLoading, setIsLoading] = useState(false);
  const [tentativasRestantes, setTentativasRestantes] = useState(3);

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    setIsLoading(true);
    setErrors({});

    // Validar email
    if (!validateEmail(formData.email)) {
      setErrors({ email: 'Email inválido' });
      setIsLoading(false);
      return;
    }

    // Verificar se email está autorizado
    if (!EMAILS_AUTORIZADOS.includes(formData.email)) {
      setErrors({ email: 'Email não autorizado para acesso' });
      setIsLoading(false);
      return;
    }

    // Verificar senha
    if (formData.password !== SENHA_PADRAO) {
      if (tentativasRestantes <= 1) {
        setErrors({ general: 'Número de tentativas excedido. Tente novamente mais tarde.' });
        setTimeout(() => {
          setTentativasRestantes(3);
          setErrors({});
        }, 30000); // Bloquear por 30 segundos
      } else {
        setErrors({ password: `Senha incorreta. Tentativas restantes: ${tentativasRestantes - 1}` });
        setTentativasRestantes(tentativasRestantes - 1);
      }
      setIsLoading(false);
      return;
    }

    // Login bem-sucedido - salvar no localStorage
    try {
      const userData = {
        uid: 'user_' + Date.now(),
        email: formData.email,
        loginTime: new Date().toISOString()
      };
      
      localStorage.setItem('reb_user', JSON.stringify(userData));
      
      // Resetar tentativas
      setTentativasRestantes(3);
      
      // Recarregar página para o App detectar o login
      window.location.reload();
      
    } catch (error) {
      setErrors({ general: 'Erro ao fazer login. Tente novamente.' });
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
        <div className="flex justify-center mb-8">
          <div className="bg-blue-600 p-3 rounded-full">
            <User className="w-8 h-8 text-white" />
          </div>
        </div>

        <h2 className="text-2xl font-bold text-center text-gray-800 mb-2">
          Acesso Restrito
        </h2>
        <p className="text-center text-gray-600 mb-8">
          Sistema para corretores de imóveis
        </p>

        {errors.general && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-6 flex items-center gap-2">
            <AlertCircle className="w-5 h-5" />
            {errors.general}
          </div>
        )}

        {/* Indicador de tentativas restantes */}
        {tentativasRestantes < 3 && (
          <div className="bg-yellow-50 border border-yellow-200 text-yellow-700 px-4 py-2 rounded-lg mb-4 text-sm">
            Tentativas restantes: {tentativasRestantes}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Email Autorizado
            </label>
            <div className="relative">
              <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                className={`pl-10 w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                  errors.email ? 'border-red-300 focus:ring-red-500' : 'border-gray-300'
                }`}
                placeholder="seu@email.com"
                required
              />
            </div>
            {errors.email && (
              <p className="mt-1 text-sm text-red-600">{errors.email}</p>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Senha de Acesso
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
              <input
                type={showPassword ? 'text' : 'password'}
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
                className={`pl-10 pr-10 w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent ${
                  errors.password ? 'border-red-300 focus:ring-red-500' : 'border-gray-300'
                }`}
                placeholder="•••"
                required
                maxLength={10}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
              </button>
            </div>
            {errors.password && (
              <p className="mt-1 text-sm text-red-600">{errors.password}</p>
            )}
            <p className="mt-2 text-xs text-gray-500">
              Digite a senha de acesso fornecida
            </p>
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="w-full bg-blue-600 text-white py-3 rounded-lg font-semibold hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isLoading ? 'Verificando...' : 'Acessar Sistema'}
          </button>
        </form>

        {/* Informações de acesso */}
        <div className="mt-6 p-4 bg-blue-50 rounded-lg">
          <div className="flex items-center gap-2 mb-2">
            <Shield className="w-4 h-4 text-blue-600" />
            <span className="text-sm font-medium text-blue-800">Acesso Restrito</span>
          </div>
          <p className="text-xs text-blue-700">
            Apenas emails autorizados têm acesso ao sistema. 
            Para solicitar acesso, entre em contato com o administrador.
          </p>
        </div>

        {/* Selo de Segurança */}
        <div className="mt-6 pt-6 border-t border-gray-200">
          <div className="flex items-center justify-center gap-2 text-xs text-gray-500">
            <Shield className="w-4 h-4" />
            <span>Sistema protegido com autenticação restrita</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SimpleLogin;
